motionRules:
@media (prefers-reduced-motion: no-preference) {
  #viewSeg::before, #audienceSeg::before, .tabs::before, .mix-switch::before { transition: transform 140ms var(--ease-ui) !important; }
  .reco, .bt-verdict, .replay-disclosure[open] > .actual, [data-reveal-outcome][open] > .actual, [data-bt-action][open] > p, [data-bt-outcome][open] > p, .pc-body:not([hidden]) { animation: 140ms ease-out 0s 1 normal none running feedback-reveal !important; }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation: auto ease 0s 1 normal none running none !important; transition: none !important; scroll-behavior: auto !important; }
}
